async function activeInjuries(){return (await HealthDB.getAll('injuries')).filter(i=>i.active!==false&&!i.endDate).sort((a,b)=>b.startDate.localeCompare(a.startDate)||String(b.createdAt||'').localeCompare(String(a.createdAt||'')));}
async function latestActiveInjury(){return (await activeInjuries())[0]||null;}
function injuryName(i){if(!i)return '';const side=i.side&&i.side!=='N/A'?`${i.side.toLowerCase()} `:'';return `${side}${String(i.area||'injury').toLowerCase()}`;}
function injuryRestrictionLabel(i){return ({modified:'Modify training',no_run:'Running paused',recovery:'Recovery focus'})[i?.restriction]||'Adapt training';}
function injuryAllowedLabels(i){const map={walk:'Short comfortable walk',swim:'Swimming',cycle:'Easy cycling',upper_strength:'Upper-body strength',lower_strength:'Lower-body strength',mobility:'Gentle mobility'};return (i?.allowed||[]).map(k=>map[k]).filter(Boolean);}
function adjustedHabitDefs(injury){return HABIT_DEFS.map(d=>{if(d.key!=='training'||!injury)return d;if(injury.restriction==='recovery')return {...d,label:'Recovery plan / intentional rest',icon:'🩹',detail:'Recovery is the training decision today'};if(injury.restriction==='no_run')return {...d,label:'Injury-safe movement',icon:'🩹',detail:'Use only an alternative you have marked as comfortable'};return {...d,label:'Modified training / movement',icon:'🩹',detail:'Adapt the plan rather than abandoning the day'};});}
function dayPhase(){const h=new Date().getHours();if(h<11)return {key:'morning',label:'BUILDING',headline:'Build today’s momentum',detail:'Start with the small wins. Your score is meant to grow through the day.'};if(h<17)return {key:'day',label:'IN PROGRESS',headline:'Keep the day moving',detail:'You do not need perfection — just the next useful action.'};if(h<21)return {key:'evening',label:'FINISH STRONG',headline:'Bank the day',detail:'There is still time to rescue or strengthen today’s score.'};return {key:'late',label:'DAY CLOSE',headline:'Finish, learn, reset',detail:'Close the easy gaps, then let tomorrow start fresh.'};}
function nextWin(h,defs,injury){const order=['vitamins','learning','water','checkin','steps','protein','fibre','nutrition','training','weighIn','bedtime'];const unfinished=order.map(k=>defs.find(d=>d.key===k)).filter(d=>d&&!h[d.key]);const d=unfinished[0];if(!d)return {title:'Everything banked',detail:'You have completed every Momentum action available today.',icon:'🏆',key:null,points:0};let detail=d.detail;if(d.key==='training'&&injury){const opts=injuryAllowedLabels(injury);detail=injury.restriction==='recovery'?'Mark intentional recovery when you have protected the injury and followed your recovery plan.':opts.length?`Choose one you marked okay: ${opts.slice(0,3).join(', ')}.`:'Use only movement you already know is comfortable; otherwise make recovery the win.';}return {title:d.label,detail,icon:d.icon,key:d.key,points:d.points};}
function nextWinButton(next){if(!next.key)return '';const inputMap={vitamins:'vitamins',nutrition:'nutrition',protein:'nutrition',fibre:'nutrition',steps:'today',water:'today',checkin:'checkin',weighIn:'weight',training:'activity'};if(next.key==='learning')return `<button class="primary-btn" data-open-current-lesson="1">Open lesson</button>`;if(inputMap[next.key])return `<button class="primary-btn" data-open-input="${inputMap[next.key]}">${next.key==='weighIn'?'Log it':next.key==='training'?'Log activity':'Open'}</button>`;return `<button class="primary-btn" data-next-habit="${next.key}">Bank it</button>`;}
function injuryCard(injury,context='today'){if(!injury)return '';const days=Math.max(1,daysBetween(injury.startDate,isoDate())+1);const allowed=injuryAllowedLabels(injury);const activityCopy=injury.restriction==='recovery'?'Exercise targets are temporarily replaced by intentional recovery.':allowed.length?`Options you marked as okay: ${allowed.join(' • ')}`:'No alternatives selected — recovery can be the correct choice.';const check=(injury.checkins||[]).find(c=>c.date===isoDate());const checkLabel=check?({better:'Better',same:'Same',worse:'Worse'}[check.status]||check.status):null;return `<section class="card injury-card"><div class="goal-head"><div><strong>🩹 ${esc(injury.area||'Injury')} active · Day ${days}</strong><small>${esc(injuryRestrictionLabel(injury))}${injury.side&&injury.side!=='N/A'?` • ${esc(injury.side)}`:''} • ${esc(injury.severity||'Not rated')}</small></div><span class="pill ${injury.restriction==='recovery'?'bad':'watch'}">ADAPTED</span></div><p>${esc(activityCopy)}</p>${injury.note?`<div class="injury-note">${esc(injury.note)}</div>`:''}<div class="injury-checkin"><span>How is it today?</span>${checkLabel?`<b>${esc(checkLabel)} ✓</b>`:`<div class="injury-check-buttons"><button class="mini-choice" data-injury-check="better" data-injury-id="${injury.id}">Better</button><button class="mini-choice" data-injury-check="same" data-injury-id="${injury.id}">Same</button><button class="mini-choice" data-injury-check="worse" data-injury-id="${injury.id}">Worse</button></div>`}</div><div class="button-row" style="margin-top:10px"><button class="secondary-btn" id="editActiveInjury" data-injury-id="${injury.id}">Update injury</button><button class="secondary-btn" id="resolveActiveInjury" data-injury-id="${injury.id}">Mark resolved</button></div></section>`;}
function injuryHistoryRow(i){const end=i.endDate?` → ${fmtDate(i.endDate,{day:'numeric',month:'short'})}`:' • active';return `<div class="journal-row"><strong>🩹 ${esc(i.area||'Injury')} ${esc(i.side&&i.side!=='N/A'?`• ${i.side}`:'')}</strong><small>${fmtDate(i.startDate,{day:'numeric',month:'short'})}${end} • ${esc(injuryRestrictionLabel(i))}</small>${i.note?`<p>${esc(i.note)}</p>`:''}</div>`;}

async function render(){
  state.profile=await HealthDB.get('profile','main')||state.profile;
  const titles={today:'Today',progress:'Progress',running:'Running',learn:'Learn',more:'More',settings:'Settings'};
  document.getElementById('pageTitle').textContent=titles[state.view]||'Health';
  const app=document.getElementById('app');
  if(state.view==='today')app.innerHTML=await renderToday();
  if(state.view==='progress')app.innerHTML=await renderProgress();
  if(state.view==='running')app.innerHTML=await renderRunning();
  if(state.view==='learn')app.innerHTML=await renderLearn();
  if(state.view==='more')app.innerHTML=await renderMore();
  if(state.view==='settings')app.innerHTML=await renderSettings();
  const demoMode=await HealthDB.get('settings','demoMode');
  if(demoMode?.active&&state.view!=='settings')app.insertAdjacentHTML('afterbegin',`<section class="notice demo-banner"><strong>🧪 TEST DRIVE</strong> Synthetic data is loaded. Reset it in Settings before Day 1.</section>`);
  bindViewEvents();
}

