async function coachText(h,latest,avg7,change,trajectory,injury,defs=HABIT_DEFS){
  const m=momentum(h,defs);const p=state.profile;const phase=dayPhase();
  if(injury){const allowed=injuryAllowedLabels(injury);if(injury.restriction==='recovery')return `Recovery is the plan today. You are not losing Momentum by protecting your ${injuryName(injury)}. Bank the controllables: nutrition, vitamins, learning and the recovery decision itself.`;if(injury.restriction==='no_run')return `Running is paused while your ${injuryName(injury)} settles. Your health journey is not. ${allowed.length?`A ${allowed[0].toLowerCase()} can count as today’s movement if it remains comfortable.`:'Use recovery as the movement decision today.'}`;if(m.earned<55&&phase.key==='evening')return `The injury changes the route, not the goal. Pick two safe wins tonight — one can be your adapted movement or recovery plan.`;}
  if(!latest)return 'Start with one simple win: log today’s weight. The dashboard will become more useful as your trend builds.';
  if(change!=null&&change<-.2&&m.earned>=70)return `Your 7-day weight trend is down ${Math.abs(change).toFixed(1)} lb and today’s Momentum is already ${m.earned}. Keep doing the boring things well.`;
  if(avg7!=null&&trajectory!=null&&avg7<=trajectory)return `Your 7-day average is on or ahead of the trajectory needed for ${p.madridWeight} lb by Madrid. Protect the behaviours rather than chasing a faster drop.`;
  if(m.earned<55&&phase.key==='evening')return `Today needs rescuing. You still have ${100-m.earned} points available. Pick the easiest two unfinished actions and finish the day with momentum.`;
  if(m.earned>=85)return `Excellent day so far. You do not need to make it harder — finish the remaining easy wins and bank the consistency.`;
  if(phase.key==='morning')return `The score is supposed to be low this morning. Start with the easy controllables and let Momentum build rather than judging the day too early.`;
  return `You are building the evidence. Today’s job is not to force the scale; it is to complete enough controllable actions that the long-term trend becomes hard to avoid.`;
}

async function weeklyPriorities(injury=null){
  const p=state.profile;const weekStart=mondayOf();const habits=(await HealthDB.getAll('habits')).filter(h=>h.date>=weekStart&&h.date<=isoDate());const acts=(await HealthDB.getAll('activities')).filter(a=>a.date>=weekStart&&a.date<=isoDate());
  const strength=acts.filter(a=>a.type==='strength').length;const nutrition=habits.filter(h=>h.nutrition).length;const weigh=habits.filter(h=>h.weighIn).length;const priorities=[];
  if(injury?.restriction==='recovery'){priorities.push({icon:'🩹',title:'Protect recovery',detail:`Your ${injuryName(injury)} is active. Recovery replaces the normal training target for now.`});}
  else if(injury?.restriction==='no_run'){const allowed=injuryAllowedLabels(injury);priorities.push({icon:'🩹',title:'Keep moving safely',detail:allowed.length?`Choose only from your comfortable alternatives: ${allowed.slice(0,3).join(', ')}.`:'No alternative is required if recovery is the right choice.'});}
  else if(strength<(p.strengthTarget||2))priorities.push({icon:'💪',title:`Complete ${Math.max(1,(p.strengthTarget||2)-strength)} strength session${(p.strengthTarget||2)-strength===1?'':'s'}`,detail:'Strength is the consistency gap we want to close.'});
  if(nutrition<Math.max(1,habits.length-1))priorities.push({icon:'🥗',title:'Protect the nutrition average',detail:'One normal planned day is more useful than a dramatic correction.'});
  if(weigh<habits.length)priorities.push({icon:'⚖',title:'Keep the weigh-in streak alive',detail:'More data makes the trend calmer and more useful.'});
  if(p.weeklyRunTarget&&(!injury||injury.restriction==='modified')){const miles=sum(acts.filter(a=>a.type==='run'),a=>a.distanceMiles);if(miles<p.weeklyRunTarget)priorities.push({icon:'🏃',title:`Build towards ${p.weeklyRunTarget} miles`,detail:`${round(miles,1)} miles logged so far this week.`});}
  priorities.push({icon:'💊',title:'Take the vitamins today',detail:'Small, boring, repeatable win.'},{icon:'🧠',title:'Complete today’s lesson',detail:'The long game is changing the behaviour, not just the number.'});
  return priorities.slice(0,3);
}

function seasonalCoachCard(){
  const today=isoDate();const md=today.slice(5);let title='',body='',emoji='';
  if(md>='12-01'&&md<='12-26'){emoji='🎄';title='Christmas Navigator';body='Enjoy Christmas deliberately. Protect the habits that matter, plan the occasions you care about, and avoid turning one celebration into a month-long write-off.';}
  else if(md>='12-27'||md<='01-07'){emoji='↩';title='New Year without the restart';body='There is no need for punishment or a dramatic reset. Return to your normal plan at the next meal and let the average recover.';}
  else if(daysTo(state.profile.madridDate)<=14&&isoDate()<=state.profile.madridDate){emoji='🏁';title='Race priorities have changed';body='The marathon is close. Performance and fuelling matter more now than forcing the fastest possible weight loss. Protect the work you have done.';}
  return title?`<section class="card coach"><h3>${emoji} ${title}</h3><p>${body}</p></section>`:'';
}

async function healthPerformanceScore(){
  if(!isJourneyStarted())return {score:null,metrics:[],weightTotal:0};
  const p=state.profile;const allHabits=await HealthDB.getAll('habits');const from=addDays(isoDate(),-6);const recent=allHabits.filter(h=>h.date>=from&&h.date<=isoDate());const injury=await latestActiveInjury();const metrics=[];
  const add=(label,value,weight,formula,next)=>{if(value==null||!Number.isFinite(value))return;value=clamp(round(value,0),0,100);metrics.push({label,value,weight,points:round(value*weight/100,1),formula,next});};
  if(recent.length)add('Consistency',avg(recent.map(h=>momentum(h,adjustedHabitDefs(injury)).earned)),25,'Average Momentum score across the last 7 days.','Complete the highest-value unfinished daily actions.');
  const avg7=await sevenDayWeightAverage(),traj=weightTrajectory(p);if(avg7!=null&&traj!=null){const behind=avg7-traj;add('Weight trajectory',behind<=0?100:100-behind*10,25,`7-day average (${round(avg7,1)} lb) versus the straight-line Madrid path (${round(traj,1)} lb).`,`Keep the trend at or below the Madrid path; no extra credit for losing faster.`);}
  if(recent.length){const nutritionHit=recent.filter(h=>h.nutrition).length/recent.length*100;add('Nutrition',nutritionHit,20,`${recent.filter(h=>h.nutrition).length} of ${recent.length} recent days hit the calorie target.`,`Improve the weekly average rather than compensating after one high day.`);}
  const acts=(await HealthDB.getAll('activities')).filter(a=>a.date>=mondayOf()&&a.date<=isoDate());
  if(injury&&injury.restriction!=='modified'){const adapted=recent.length?recent.filter(h=>h.training).length/recent.length*100:null;add('Adaptation',adapted,15,'While running is restricted, this uses injury-safe movement or intentional recovery instead of mileage.','Follow the restrictions you set and bank safe movement/recovery decisions.');}
  else if(p.weeklyRunTarget){const miles=sum(acts.filter(a=>a.type==='run'),a=>a.distanceMiles);add('Running',miles/p.weeklyRunTarget*100,15,`${round(miles,1)} of ${p.weeklyRunTarget} planned miles this week.`,`Build towards the weekly target without exceeding it for score purposes.`);}
  else if(recent.length)add('Movement',recent.filter(h=>h.training).length/recent.length*100,15,'Share of recent days where planned movement/training was completed.','Complete the movement you planned for the day.');
  if(p.strengthTarget&&injury?.restriction!=='recovery'){const strength=acts.filter(a=>a.type==='strength').length;add('Strength',strength/p.strengthTarget*100,10,`${strength} of ${p.strengthTarget} strength sessions this week.`,`Complete ${Math.max(0,p.strengthTarget-strength)} more planned strength session${Math.max(0,p.strengthTarget-strength)===1?'':'s'}.`);}
  const lessons=await HealthDB.getAll('lessons');const completedRecent=lessons.filter(l=>l.completedAt&&isoDate(new Date(l.completedAt))>=from&&isoDate(new Date(l.completedAt))<=isoDate()).length;const expected=Math.max(1,Math.min(7,journeyDay()));add('Learning',completedRecent/expected*100,5,`${completedRecent} lessons completed across ${expected} available programme day${expected===1?'':'s'}.`,'Complete today’s lesson rather than simply ticking it off.');
  const weightTotal=sum(metrics,m=>m.weight);if(!weightTotal)return {score:null,metrics:[],weightTotal:0};
  const score=round(sum(metrics,m=>m.points)/weightTotal*100,0);return {score,metrics,weightTotal};
}

async function weeklyReviewCard(){
  if(!isJourneyStarted())return `<section class="card"><div class="goal-head"><div><strong>First weekly review</strong><small>Starts ${fmtDate(state.profile.startDate,{day:'numeric',month:'short'})}</small></div><span class="pill">PRE-SEASON</span></div><p class="metric-sub" style="margin-top:10px">Your first real review will build from your Day 1 data rather than treating setup week as performance data.</p></section>`;
  const weekStart=mondayOf();const weights=(await weightRows()).filter(w=>w.date>=weekStart&&w.date<=isoDate());const acts=(await HealthDB.getAll('activities')).filter(a=>a.date>=weekStart&&a.date<=isoDate());const habits=(await HealthDB.getAll('habits')).filter(h=>h.date>=weekStart&&h.date<=isoDate());
  const delta=weights.length>=2?round(Number(weights.at(-1).value)-Number(weights[0].value),1):null;const miles=round(sum(acts.filter(a=>a.type==='run'),a=>a.distanceMiles),1);const strength=acts.filter(a=>a.type==='strength').length;const vit=habits.filter(h=>h.vitamins).length;const nutrition=habits.filter(h=>h.nutrition).length;const avgMomentum=habits.length?round(avg(habits.map(h=>momentum(h).earned)),0):null;
  const reflection=await HealthDB.get('checkins',`weekly_${weekStart}`);return `<section class="card"><div class="goal-head"><div><strong>This week's review</strong><small>${fmtDate(weekStart,{day:'numeric',month:'short'})} – ${fmtDate(isoDate(),{day:'numeric',month:'short'})}</small></div>${avgMomentum!=null?`<span class="pill ${avgMomentum>=70?'good':avgMomentum>=55?'watch':'bad'}">${avgMomentum}/100</span>`:'<span class="pill">BUILDING</span>'}</div><div class="grid-2" style="margin-top:12px"><div class="metric-card"><div class="metric-label">WEIGHT</div><div class="metric-value">${delta==null?'—':`${delta>0?'+':''}${delta} lb`}</div><div class="metric-sub">first to latest this week</div></div><div class="metric-card"><div class="metric-label">RUNNING</div><div class="metric-value">${miles} mi</div><div class="metric-sub">${acts.filter(a=>a.type==='run').length} runs</div></div><div class="metric-card"><div class="metric-label">STRENGTH</div><div class="metric-value">${strength}</div><div class="metric-sub">sessions</div></div><div class="metric-card"><div class="metric-label">VITAMINS / NUTRITION</div><div class="metric-value">${vit} / ${nutrition}</div><div class="metric-sub">successful days</div></div></div>${reflection?`<div class="weekly-reflection-summary"><strong>Your view: ${reflection.rating}/5 week • confidence ${reflection.confidence}/5</strong><p>${esc(reflection.wentWell||'')}${reflection.improve?` • Next: ${esc(reflection.improve)}`:''}</p></div>`:''}<button class="secondary-btn wide" id="weeklyReflection" style="margin-top:12px">${reflection?'Update my reflection':'Add my weekly reflection'}</button></section>`;
}

async function renderStreaks(){
  const habits=(await HealthDB.getAll('habits')).sort((a,b)=>b.date.localeCompare(a.date));
  const defs=[['weighIn','⚖','Weigh-ins'],['vitamins','💊','Vitamins'],['nutrition','🥗','Nutrition'],['learning','🧠','Learning']];
  return defs.map(([key,emoji,label])=>{let streak=0;let d=isoDate();for(let i=0;i<500;i++){const r=habits.find(x=>x.date===d);if(r?.[key]){streak++;d=addDays(d,-1);}else if(i===0){d=addDays(d,-1);continue;}else break;}return `<div class="streak"><span class="emoji">${emoji}</span><strong>${streak} day${streak===1?'':'s'}</strong><small>${label}</small></div>`;}).join('');
}

async function todayLessonCard(){
  const day=journeyDay();const lessons=(await HealthDB.getAll('lessons')).sort((a,b)=>a.day-b.day);const lesson=lessons.find(l=>l.day===day)||lessons.find(l=>!l.completedAt)||lessons[0];if(!lesson)return '';
  return `<div class="section-title"><h2>Today's lesson</h2><span>${lesson.minutes} min</span></div><section class="card"><div class="lesson-card ${lesson.completedAt?'completed':''}" style="border:0;padding:0"><div class="lesson-number">${lesson.completedAt?'✓':lesson.day}</div><div><strong>${esc(lesson.title)}</strong><small>${esc(lesson.theme)} • Day ${lesson.day} of the programme</small></div><button class="secondary-btn" data-open-lesson="${lesson.id}">${lesson.completedAt?'Review':'Start'}</button></div></section>`;
}

async function renderProgress(){
  const p=state.profile;const stats=await weightProgressStats();const weights=stats.rows;const latest=stats.latest;const start=p.startWeight;
  const progress=(start&&latest&&start>p.ultimateWeight)?clamp((start-Number(latest.value))/(start-p.ultimateWeight)*100,0,100):0;
  const rangeStart=weightRangeStart();const visible=rangeStart?weights.filter(w=>w.date>=rangeStart):weights;
  const chart=weightChart(visible,p,weights);
  const milestones=[];if(start){for(let w=Math.floor(start/5)*5;w>=p.ultimateWeight;w-=5)milestones.push(w);if(!milestones.includes(p.ultimateWeight))milestones.push(p.ultimateWeight);}
  const hp=await healthPerformanceScore();const insight=weightInsight(stats,p);
  const nextMilestone=milestones.find(w=>latest&&Number(latest.value)>w);const nextMilestoneGap=nextMilestone&&latest?round(Number(latest.value)-nextMilestone,1):null;
  const trajectoryLabel=stats.trajectoryDelta==null?'BUILDING':stats.trajectoryDelta<=0?`${Math.abs(stats.trajectoryDelta).toFixed(1)} LB AHEAD`:`${stats.trajectoryDelta.toFixed(1)} LB BEHIND`;
  const trajectoryClass=stats.trajectoryDelta==null?'':stats.trajectoryDelta<=0?'good':'watch';
  const rangeButtons=[['30d','30D'],['90d','90D'],['6m','6M'],['all','ALL']].map(([key,label])=>`<button class="range-btn ${state.progressRange===key?'active':''}" data-weight-range="${key}">${label}</button>`).join('');
  return `<div class="screen-head"><div><h2>Your transformation</h2><p>Trend over noise. Progress over perfection.</p></div><button class="primary-btn" id="addWeight">+ Weight</button></div>
    <section class="card progress-hero"><div class="goal-head"><div><div class="metric-label">ROAD TO MADRID</div><strong>${stats.avg7!=null?`${round(stats.avg7,1)} lb trend`:latest?`${round(Number(latest.value),1)} lb`:'Baseline pending'}</strong><small>${stats.avg7!=null?'7-day average':latest?lbsToStone(Number(latest.value)):'Start 3 November'}</small></div><span class="pill ${trajectoryClass}">${trajectoryLabel}</span></div><div class="progress-track" style="margin-top:16px"><div class="progress-fill" style="width:${progress}%"></div></div><div class="goal-scale"><span>${start?`${start} start`:'Start'}</span><span>${p.madridWeight} Madrid</span><span>${p.ultimateWeight} ultimate</span></div><div class="progress-summary"><div><b>${stats.loss!=null?`${Math.max(0,stats.loss)} lb`:'—'}</b><span>lost</span></div><div><b>${stats.toMadrid!=null?`${Math.max(0,stats.toMadrid)} lb`:'—'}</b><span>to Madrid</span></div><div><b>${stats.toUltimate!=null?`${Math.max(0,stats.toUltimate)} lb`:'—'}</b><span>to ultimate</span></div></div></section>
    <section class="insight-card ${insight.tone}"><div class="insight-icon">${insight.icon}</div><div><strong>${esc(insight.title)}</strong><p>${esc(insight.body)}</p></div></section>
    <section class="grid-2"><div class="metric-card"><div class="metric-label">CURRENT PACE</div><div class="metric-value">${stats.weeklyLoss!=null?`${stats.weeklyLoss>=0?'↓ ':'↑ '}${Math.abs(stats.weeklyLoss).toFixed(1)} lb/wk`:'—'}</div><div class="metric-sub">7-day average vs prior week</div></div><div class="metric-card"><div class="metric-label">PACE NEEDED</div><div class="metric-value">${stats.requiredWeekly!=null?`${Math.max(0,stats.requiredWeekly).toFixed(1)} lb/wk`:'—'}</div><div class="metric-sub">Straight line to ${p.madridWeight} lb</div></div><div class="metric-card"><div class="metric-label">MADRID FORECAST</div><div class="metric-value forecast-date">${stats.madridProjection?fmtDate(stats.madridProjection,{day:'numeric',month:'short'}):'—'}</div><div class="metric-sub">${stats.madridProjection?(stats.madridProjection<=p.madridDate?'At current trend':'Later than target'):'Build 2 weeks of trend data'}</div></div><div class="metric-card"><div class="metric-label">NEXT MILESTONE</div><div class="metric-value">${nextMilestone?`${nextMilestone} lb`:(latest&&Number(latest.value)<=p.ultimateWeight?'Goal!':'—')}</div><div class="metric-sub">${nextMilestoneGap!=null?`${nextMilestoneGap} lb away`:'Every 5 lb counts'}</div></div></section>
    <section class="card tappable-card" id="explainHPScore"><div class="goal-head"><div><strong>Health & Performance score</strong><small>Tap to see exactly how every point is calculated.</small></div><span class="pill ${hp.score==null?'':hp.score>=70?'good':hp.score>=55?'watch':'bad'}">${hp.score==null?'BUILDING':`${hp.score}/100`}</span></div>${hp.metrics.length?`<div class="score-breakdown" style="margin-top:12px">${hp.metrics.map(m=>`<div class="score-item"><div><span>${esc(m.label)} <small>(${m.weight}%)</small></span><div class="mini-bar"><div style="width:${m.value}%"></div></div></div><b>${m.value}</b></div>`).join('')}</div><div class="tap-hint">Tap for score maths and the fastest ways to improve it →</div>`:'<div class="metric-sub" style="margin-top:10px">This wakes up as your first week of data builds.</div>'}</section>
    <div class="section-title"><h2>Weight trend</h2><div class="range-control">${rangeButtons}</div></div><section class="card">${chart}<div class="chart-legend"><span><i class="raw"></i>Daily</span><span><i class="trend"></i>7-day trend</span><span><i class="target"></i>Madrid path</span></div></section>
    <div class="section-title"><h2>Milestones</h2><span>Every 5 lb counts</span></div><div class="milestones">${milestones.length?milestones.map(w=>`<div class="milestone ${latest&&Number(latest.value)<=w?'hit':''}"><strong>${w}</strong><small>lb ${latest&&Number(latest.value)<=w?'✓':'target'}</small></div>`).join(''):'<div class="empty">Add your starting weight to create milestones.</div>'}</div>
    <div class="section-title"><h2>Weekly review</h2><span>Accountability</span></div>${await weeklyReviewCard()}
    <div class="section-title"><h2>Beyond the scale</h2><button class="link-btn" id="addWaist">Add waist</button></div>${await bodySecondaryMetrics()}`;
}

function weightChart(rows,p,allRows=rows){
  if(rows.length<2)return `<div class="empty"><span class="emoji">📈</span>Two weigh-ins will unlock your first trend line.</div>`;
  const firstDate=rows[0].date,lastDate=rows.at(-1).date,totalDays=Math.max(1,daysBetween(firstDate,lastDate));
  const trendRows=rows.map(r=>({date:r.date,value:rollingAverageAt(allRows,r.date,7)})).filter(r=>r.value!=null);
  const targetRows=p.startWeight?rows.map(r=>({date:r.date,value:weightTrajectory(p,r.date)})).filter(r=>r.value!=null):[];
  const vals=[...rows.map(r=>Number(r.value)),...trendRows.map(r=>r.value),...targetRows.map(r=>r.value)].filter(Number.isFinite);
  const min=Math.min(...vals)-1.5,max=Math.max(...vals)+1.5,W=320,H=168,pad=25;
  const x=date=>pad+(daysBetween(firstDate,date)/totalDays)*(W-pad*2);const y=v=>pad+(max-v)/(max-min)*(H-pad*2);
  const rawPts=rows.map(r=>`${x(r.date)},${y(Number(r.value))}`).join(' ');const trendPts=trendRows.map(r=>`${x(r.date)},${y(r.value)}`).join(' ');const targetPts=targetRows.map(r=>`${x(r.date)},${y(r.value)}`).join(' ');
  const labels=[max,(max+min)/2,min];
  return `<div class="chart weight-chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Weight trend chart">${labels.map(v=>`<line class="chart-grid" x1="${pad}" x2="${W-pad}" y1="${y(v)}" y2="${y(v)}"></line><text class="chart-label" x="0" y="${y(v)+3}">${round(v,0)}</text>`).join('')}${targetPts?`<polyline class="chart-line target-line" points="${targetPts}"></polyline>`:''}<polyline class="chart-line raw-line" points="${rawPts}"></polyline>${trendPts?`<polyline class="chart-line trend-line" points="${trendPts}"></polyline>`:''}${rows.map(r=>`<circle class="chart-dot" cx="${x(r.date)}" cy="${y(Number(r.value))}" r="2.6"></circle>`).join('')}<text class="chart-label" x="${pad}" y="${H}">${esc(fmtDate(firstDate,{day:'numeric',month:'short'}))}</text><text class="chart-label" text-anchor="end" x="${W-pad}" y="${H}">${esc(fmtDate(lastDate,{day:'numeric',month:'short'}))}</text></svg></div>`;
}
async function bodySecondaryMetrics(){const waist=await latestMeasurement('waist');const photos=(await HealthDB.getAll('measurements')).filter(x=>x.type==='photo').length;return `<section class="grid-2"><div class="metric-card"><div class="metric-label">WAIST</div><div class="metric-value">${waist?`${waist.value} ${waist.unit||'in'}`:'—'}</div><div class="metric-sub">Periodic non-scale progress</div></div><div class="metric-card"><div class="metric-label">PROGRESS PHOTOS</div><div class="metric-value">${photos}</div><div class="metric-sub">Planned for a later release</div></div></section>`;}

async function renderRunning(){
  const activities=(await HealthDB.getAll('activities')).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));const weekStart=mondayOf();const thisWeek=activities.filter(a=>a.date>=weekStart&&a.date<=isoDate());const injury=await latestActiveInjury();
  const miles=sum(thisWeek.filter(a=>a.type==='run'),a=>a.distanceMiles);const strength=thisWeek.filter(a=>a.type==='strength').length;const runs=thisWeek.filter(a=>a.type==='run').length;const p=state.profile;const runPaused=injury&&injury.restriction!=='modified';
  return `<div class="screen-head"><div><h2>Running & training</h2><p>Garmin keeps the detail. This dashboard keeps the story.</p></div><button class="primary-btn" id="addActivity">+ Activity</button></div>
    ${injuryCard(injury,'running')}
    <section class="grid-2"><div class="metric-card"><div class="metric-label">THIS WEEK</div><div class="metric-value">${round(miles,1)} mi</div><div class="metric-sub">${runs} run${runs===1?'':'s'}${runPaused?' • target paused for injury':p.weeklyRunTarget?` • target ${p.weeklyRunTarget} mi`:''}</div></div><div class="metric-card"><div class="metric-label">STRENGTH</div><div class="metric-value">${strength}/${p.strengthTarget}</div><div class="metric-sub">sessions this week</div></div></section>
    <section class="card"><div class="goal-head"><div><strong>${runPaused?'Adapted training mix':'Weekly training mix'}</strong><small>${runPaused?'Running targets are paused; safe alternatives and recovery still count as progress.':'Start simple: run consistently and make strength happen.'}</small></div><span class="pill ${runPaused?'watch':strength>=p.strengthTarget?'good':strength?'watch':''}">${runPaused?'ADAPTED':strength>=p.strengthTarget?'DONE':`${Math.max(0,p.strengthTarget-strength)} TO GO`}</span></div><div class="progress-track" style="margin-top:12px"><div class="progress-fill" style="width:${clamp(strength/p.strengthTarget*100,0,100)}%"></div></div></section>
    <div class="section-title"><h2>Recent activity</h2><span>${activities.length} logged</span></div><section class="card compact">${activities.length?activities.slice(0,10).map(activityRow).join(''):'<div class="empty"><span class="emoji">🏃</span>Your first run, strength session, swim or football activity will appear here.</div>'}</section>
    <div class="section-title"><h2>Performance baseline</h2><button class="link-btn" id="editBaseline">Edit</button></div><section class="grid-2"><div class="metric-card"><div class="metric-label">GARMIN VO₂ MAX</div><div class="metric-value">${p.vo2max??'—'}</div><div class="metric-sub">Manual for V0.4</div></div><div class="metric-card"><div class="metric-label">RUN BASELINE</div><div class="metric-value">${p.weeklyRunBaseline!=null?`${p.weeklyRunBaseline} mi`:'—'}</div><div class="metric-sub">Typical week at launch</div></div></section>
    <div class="section-title"><h2>Race goals & PBs</h2><button class="link-btn" id="managePBs">Manage</button></div>${await raceRecords()}`;
}
function activityRow(a){const icons={run:'🏃',strength:'💪',swim:'🏊',football:'⚽',walk:'🚶',cycle:'🚴',other:'●'};return `<div class="activity-row"><div class="activity-icon">${icons[a.type]||'●'}</div><div><strong>${esc(a.title||a.type)}</strong><small>${fmtDate(a.date,{weekday:'short',day:'numeric',month:'short'})}${a.durationMinutes?` • ${a.durationMinutes} min`:''}${a.avgHr?` • ${a.avgHr} bpm`:''}</small></div><div class="activity-value">${a.distanceMiles?`${round(a.distanceMiles,2)} mi`:a.type==='strength'?'✓':''}</div></div>`;}
async function raceRecords(){const rec=await HealthDB.get('settings','raceRecords')||{id:'raceRecords'};const keys=[['5k','5K'],['10k','10K'],['10mile','10 mile'],['half','Half'],['marathon','Marathon']];return `<section class="card compact">${keys.map(([k,l])=>`<div class="source-card"><div class="source-icon">🏁</div><div><strong>${l}</strong><small>Current-era best</small></div><b>${esc(rec[k]||'—')}</b></div>`).join('')}</section>`;}

async function renderLearn(){
  const lessons=(await HealthDB.getAll('lessons')).sort((a,b)=>a.day-b.day);const completed=lessons.filter(l=>l.completedAt).length;const day=journeyDay();
  return `<div class="screen-head"><div><h2>Learn the change</h2><p>Evidence-backed coaching: read, think, answer, apply.</p></div><span class="pill ${completed?'good':''}">${completed}/${lessons.length}</span></div>
    <section class="hero ${!isJourneyStarted()?'preseason':''}"><div class="kicker">SIX-MONTH JOURNEY</div><h2>${isJourneyStarted()?`Day ${day}`:'Starts 3 November'}</h2><p>Lose weight while learning the behaviours that make maintaining it more likely.</p></section>
    <div class="section-title"><h2>Starter lessons</h2><span>Coach & professor mode</span></div><section class="card compact">${lessons.map(l=>`<div class="lesson-card ${l.completedAt?'completed':''}"><div class="lesson-number">${l.completedAt?'✓':l.day}</div><div><strong>${esc(l.title)}</strong><small>${esc(l.theme)} • ${l.minutes} min</small></div><button class="secondary-btn" data-open-lesson="${l.id}">${l.completedAt?'Review':'Open'}</button></div>`).join('')}</section>
    <div class="section-title"><h2>Programme map</h2><span>To Madrid & beyond</span></div><section class="card">${CURRICULUM.map(([title,body])=>`<div class="phase"><strong>${esc(title)}</strong><p>${esc(body)}</p></div>`).join('')}</section>
    <section class="notice warning">Seasonal coaching will sit inside this curriculum — including Christmas, New Year, travel and the changing priorities of marathon training and race week.</section>`;
}

async function renderMore(){
  const badges=await derivedBadges();const journal=(await HealthDB.getAll('journal')).sort((a,b)=>b.date.localeCompare(a.date));const injuries=(await HealthDB.getAll('injuries')).sort((a,b)=>b.startDate.localeCompare(a.startDate));const active=injuries.filter(i=>i.active!==false&&!i.endDate);
  return `<div class="screen-head"><div><h2>More</h2><p>Goals, badges, recovery, notes and connections.</p></div><button class="secondary-btn" id="openSettings">Settings</button></div>
    <div class="section-title"><h2>Badges</h2><span>${badges.filter(b=>b.hit).length}/${badges.length} unlocked</span></div><section class="badge-grid">${badges.map(b=>`<div class="badge ${b.hit?'':'locked'}"><span class="emoji">${b.emoji}</span><strong>${esc(b.title)}</strong><small>${esc(b.detail)}</small></div>`).join('')}</section>
    <div class="section-title"><h2>Injuries & recovery</h2><button class="link-btn" id="addInjury">+ Injury</button></div><section class="card compact">${injuries.length?injuries.slice(0,8).map(injuryHistoryRow).join(''):'<div class="empty"><span class="emoji">🩹</span>No structured injuries logged. Add one here when coaching needs to adapt around a niggle or restriction.</div>'}</section>
    <div class="section-title"><h2>Data sources</h2><span>V0.4 status</span></div><section class="card compact">${dataSourceRows()}</section>
    <div class="section-title"><h2>Journal</h2><button class="link-btn" id="addJournal">+ Note</button></div><section class="card compact">${journal.length?journal.slice(0,8).map(j=>`<div class="journal-row"><strong>${esc(j.type||'Note')} • ${fmtDate(j.date,{day:'numeric',month:'short'})}</strong><small>${esc(j.severity||'')}</small><p>${esc(j.note||'')}</p></div>`).join(''):'<div class="empty">Log illness, a bad night’s sleep or anything that helps explain the data later.</div>'}</section>
    <div class="section-title"><h2>Quick actions</h2></div><section class="quick-grid"><button class="quick-option" id="quickWeight"><span>⚖</span><strong>Weight</strong><small>Daily weigh-in</small></button><button class="quick-option" id="quickNutrition"><span>🥗</span><strong>Nutrition</strong><small>Nutracheck totals</small></button><button class="quick-option" id="quickActivity"><span>🏃</span><strong>Activity</strong><small>Run, gym, swim, football</small></button><button class="quick-option" id="quickInjury"><span>🩹</span><strong>Injury</strong><small>Adapt coaching and training</small></button><button class="quick-option" id="quickJournal"><span>✎</span><strong>Journal</strong><small>Illness, sleep or context</small></button></section>`;
}
function dataSourceRows(){return `
<div class="source-card"><div class="source-icon">G</div><div><strong>Garmin Forerunner 945</strong><small>Official Personal API confirmed. Activities + steps first; key must stay private.</small></div><span class="pill good">API READY</span></div>
<div class="source-card"><div class="source-icon">W</div><div><strong>Withings Body+</strong><small>Weight is the priority; body composition can provide context.</small></div><span class="pill watch">PLANNED</span></div>
<div class="source-card"><div class="source-icon">N</div><div><strong>Nutracheck</strong><small>Daily calories, protein and fibre rather than duplicating food logging.</small></div><span class="pill watch">PLANNED</span></div>`;}

async function derivedBadges(){
  const habits=await HealthDB.getAll('habits'),weights=await weightRows(),acts=await HealthDB.getAll('activities'),lessons=await HealthDB.getAll('lessons'),injuries=await HealthDB.getAll('injuries'),journal=await HealthDB.getAll('journal'),p=state.profile,latest=weights.at(-1),loss=p.startWeight&&latest?p.startWeight-Number(latest.value):0;
  const count=k=>habits.filter(h=>h[k]).length, strength=acts.filter(a=>a.type==='strength').length, runs=acts.filter(a=>a.type==='run'), swims=acts.filter(a=>a.type==='swim').length, completed=lessons.filter(l=>l.completedAt).length;
  const streak=k=>streakForRows(habits,k), moment=t=>journal.some(j=>j.type===t), weeklyMileage=sum(runs.filter(a=>a.date>=mondayOf()&&a.date<=isoDate()),a=>a.distanceMiles);
  const badges=[
    ['🚀','Journey begun','First weigh-in',weights.length>0],['⚖','Scale starter','3 weigh-ins',count('weighIn')>=3],['🥉','Scale bronze','7 weigh-ins',count('weighIn')>=7],['🥈','Scale silver','30 weigh-ins',count('weighIn')>=30],['🥇','Scale gold','100 weigh-ins',count('weighIn')>=100],
    ['💊','Pill starter','3 supplement days',count('vitamins')>=3],['🥉','Pill bronze','7 supplement days',count('vitamins')>=7],['🥈','Pill silver','30 supplement days',count('vitamins')>=30],['💎','Pill diamond','100 supplement days',count('vitamins')>=100],
    ['🧠','Curious','First lesson',completed>=1],['📚','Student','5 lessons',completed>=5],['🎓','Scholar','25 lessons',completed>=25],['🧪','Behaviour nerd','50 lessons',completed>=50],['🏛','Professor mode','100 lessons',completed>=100],
    ['💪','Strength starts','First strength session',strength>=1],['🥉','Strength bronze','5 strength sessions',strength>=5],['🥈','Strength silver','25 strength sessions',strength>=25],['🥇','Strength gold','50 strength sessions',strength>=50],
    ['🏃','In motion','First logged run',runs.length>=1],['20','Twenty-mile week','Reach 20 running miles in a week',weeklyMileage>=20],['🏊','Make a splash','First swim',swims>=1],['🩹','Adapt & continue','Log an injury and adapt',injuries.length>=1],['🛡','Recovery counts','Complete movement/recovery while injured',injuries.length>=1&&count('training')>=1],
    ['2','First two','2 lb lost',loss>=2],['5','First five','5 lb lost',loss>=5],['10','Double digits','10 lb lost',loss>=10],['🪨','Stone lighter','14 lb lost',loss>=14],['🏁','Madrid weight',`Reach ${p.madridWeight} lb`,!!latest&&Number(latest.value)<=p.madridWeight],['⭐','Ultimate',`Reach ${p.ultimateWeight} lb`,!!latest&&Number(latest.value)<=p.ultimateWeight],
    ['🔥','Seven-day fire','7-day Momentum consistency',streak('checkin')>=7],['🥗','Nutrition week','7 nutrition-target days',count('nutrition')>=7],['◉','Protein week','7 protein-target days',count('protein')>=7],['💧','Hydrated week','7 water-target days',count('water')>=7],['👟','Step week','7 step-target days',count('steps')>=7],
    ['↩','Bounce Back','Log a bounce back',moment('Bounce back')],['🧲','Not today, temptation','Log a temptation resisted',moment('Temptation resisted')],['🌧','Still showed up','Bank movement on a difficult day',count('training')>=5]
  ];
  const checkins=await HealthDB.getAll('checkins');if(checkins.filter(c=>String(c.id).startsWith('daily_')).length>=7)badges.push(['🧭','Context collector','7 daily check-ins',true]);else badges.push(['🧭','Context collector','7 daily check-ins',false]);
  return badges.map(([emoji,title,detail,hit])=>({emoji,title,detail,hit:!!hit}));
}

async function renderSettings(){
  const p=state.profile;const backup=await HealthDB.get('settings','backupMeta');const demoMode=await HealthDB.get('settings','demoMode');
  return `<div class="screen-head"><div><h2>Settings</h2><p>Local-first controls and setup.</p></div><button class="secondary-btn" id="backMore">Back</button></div>
  <section class="card">
    <div class="settings-row"><h3>Profile & targets</h3><p>Start date, Madrid target, ultimate target and daily behaviour targets.</p><button class="primary-btn" id="editProfile">Edit profile & targets</button></div>
    <div class="settings-row"><h3>Baseline</h3><p>Starting weight, waist, Garmin VO₂ max and typical weekly mileage. These can be entered on 3 November morning.</p><button class="secondary-btn" id="settingsBaseline">Edit baseline</button></div>
    <div class="settings-row"><h3>Data connections</h3><p>Garmin's official Personal API is confirmed; Withings also has an official API. V0.4 remains manual while we wire credentials without exposing them in GitHub.</p><button class="secondary-btn" id="settingsSources">View status</button></div>
    <div class="settings-row"><h3>Behaviour inputs</h3><p>Daily check-ins, hunger, workout feel, supplements, wins/wobbles and tomorrow plans stay local and give the coach context the wearables cannot know.</p><div class="button-row"><button class="secondary-btn" data-open-input="checkin">Daily check-in</button><button class="secondary-btn" data-open-input="vitamins">Supplements</button><button class="secondary-btn" data-open-input="plan">Tomorrow plan</button></div></div><div class="settings-row"><h3>Encrypted backup</h3><p>${backup?.lastBackupAt?`Last backup ${new Date(backup.lastBackupAt).toLocaleString('en-GB')}`:'No backup yet'}. Export all local Health Dashboard data into one password-encrypted <code>.healthdash</code> file.</p><div class="button-row"><button class="primary-btn" id="exportBackup">Export everything</button><button class="secondary-btn" id="importBackup">Restore backup</button><input id="backupInput" type="file" accept=".healthdash,application/octet-stream" hidden></div></div>
    <div class="settings-row"><h3>Test drive</h3><p id="testDriveCopy">${demoMode?.active?'🧪 Demo is active. Explore Today, Progress, Running and Learn, then reset to restore your exact pre-demo data.':'Load a realistic two-week demo so you can test the live dashboard before 3 November. Reset restores the exact local data you had immediately before loading the demo.'}</p><div class="button-row"><button class="primary-btn" id="loadDemoData" ${demoMode?.active?'disabled':''}>${demoMode?.active?'Demo loaded':'Load demo data'}</button><button class="secondary-btn" id="resetDemoData" ${demoMode?.active?'':'disabled'}>Reset demo</button></div></div>
    <div class="settings-row"><h3>App version</h3><p><span class="version-chip">v${APP_VERSION}</span> ${RELEASE_NAME}. Check what GitHub Pages currently has deployed or force the app shell to reload.</p><div class="button-row"><button class="secondary-btn" id="checkVersion">Check deployed version</button><button class="secondary-btn" id="reloadLatest">Reload latest</button></div></div>
    <div class="settings-row"><h3>Privacy</h3><p>Personal health information is stored in IndexedDB in this browser profile. GitHub hosts the application files, not your health records. Clearing browser/site data can remove local records, so encrypted backups matter.</p></div>
  </section>`;
}

function bindViewEvents(){
  document.querySelectorAll('[data-habit-toggle]').forEach(b=>b.onclick=()=>{const k=b.dataset.habitToggle;if(k==='learning')currentLesson().then(l=>l&&openLesson(l.id));else if(k==='checkin')openDailyCheckinModal();else if(k==='vitamins')openSupplementsModal();else if(k==='weighIn')openWeightModal();else if(['nutrition','protein','fibre'].includes(k))openNutritionModal();else if(['steps','water'].includes(k))openTodayNumbersModal();else if(k==='training')openActivityModal();else toggleHabit(k);});
  document.querySelectorAll('[data-next-habit]').forEach(b=>b.onclick=()=>toggleHabit(b.dataset.nextHabit));
  document.querySelectorAll('[data-open-current-lesson]').forEach(b=>b.onclick=()=>currentLesson().then(l=>l&&openLesson(l.id)));
  document.querySelectorAll('[data-open-lesson]').forEach(b=>b.onclick=()=>openLesson(b.dataset.openLesson));
  document.querySelectorAll('[data-nav-view]').forEach(b=>b.onclick=()=>setView(b.dataset.navView));
  document.querySelectorAll('[data-open-input]').forEach(b=>b.onclick=()=>({nutrition:openNutritionModal,today:openTodayNumbersModal,checkin:openDailyCheckinModal,plan:openTomorrowPlanModal,vitamins:openSupplementsModal,weight:openWeightModal,activity:openActivityModal}[b.dataset.openInput]?.()));
  document.querySelectorAll('.action-row[data-habit]').forEach(row=>row.onclick=e=>{if(e.target.closest('button'))return;const k=row.dataset.habit;if(k==='weighIn')setView('progress');else if(k==='training')setView('running');else if(k==='learning')currentLesson().then(l=>l&&openLesson(l.id));else if(k==='vitamins')openSupplementsModal();else if(k==='checkin')openDailyCheckinModal();else if(['nutrition','protein','fibre'].includes(k))openNutritionModal();else if(['steps','water'].includes(k))openTodayNumbersModal();});
  document.querySelectorAll('.setup-action').forEach(b=>b.onclick=()=>handleSetupAction(b.dataset.action));
  document.querySelectorAll('[data-weight-range]').forEach(b=>b.onclick=()=>{state.progressRange=b.dataset.weightRange;render();});
  document.querySelectorAll('[data-injury-check]').forEach(b=>b.onclick=()=>logInjuryCheckin(b.dataset.injuryId,b.dataset.injuryCheck));
  const map={openBaseline:openBaselineModal,addWeight:openWeightModal,addWaist:openWaistModal,addActivity:openActivityModal,addInjury:()=>openInjuryModal(),editBaseline:openBaselineModal,editTodayNumbers:openTodayNumbersModal,openSettings:()=>{state.view='settings';render();},quickWeight:openWeightModal,quickNutrition:openNutritionModal,quickActivity:openActivityModal,quickInjury:()=>openInjuryModal(),quickJournal:openJournalModal,addJournal:openJournalModal,backMore:()=>setView('more'),editProfile:openProfileModal,settingsBaseline:openBaselineModal,settingsSources:openSourcesModal,managePBs:openPBModal,explainHPScore:openScoreBreakdown,weeklyReflection:openWeeklyReflectionModal,explainMomentum:openMomentumBreakdown};
  for(const [id,fn] of Object.entries(map)){const el=document.getElementById(id);if(el)el.onclick=fn;}
  const editInjury=document.getElementById('editActiveInjury');if(editInjury)editInjury.onclick=()=>openInjuryModal(editInjury.dataset.injuryId);
  const resolveInjuryBtn=document.getElementById('resolveActiveInjury');if(resolveInjuryBtn)resolveInjuryBtn.onclick=()=>resolveInjury(resolveInjuryBtn.dataset.injuryId);
  const exp=document.getElementById('exportBackup');if(exp)exp.onclick=exportEncryptedBackup;
  const imp=document.getElementById('importBackup');if(imp)imp.onclick=()=>document.getElementById('backupInput').click();
  const input=document.getElementById('backupInput');if(input)input.onchange=e=>{if(e.target.files?.[0])restoreEncryptedBackup(e.target.files[0]);};
  const demo=document.getElementById('loadDemoData');if(demo)demo.onclick=loadDemoData;
  const reset=document.getElementById('resetDemoData');if(reset)reset.onclick=resetDemoData;
  const cv=document.getElementById('checkVersion');if(cv)cv.onclick=checkDeployedVersion;
  const rl=document.getElementById('reloadLatest');if(rl)rl.onclick=reloadLatest;
}

async function toggleHabit(key){const h=await habitFor();h[key]=!h[key];await saveHabit(h);render();}
function handleSetupAction(action){if(action==='profile')openProfileModal();else if(action==='baseline')openBaselineModal();else openSourcesModal();}

function openProfileModal(){const p=state.profile;modal(`<div class="modal-head"><div><h2>Profile & targets</h2><p>These drive your scores, trajectory and daily cards.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="profileForm" class="form-grid">
<div class="form-grid cols-2"><div class="field"><label>Name</label><input name="name" value="${esc(p.name)}"></div><div class="field"><label>Journey start</label><input type="date" name="startDate" value="${p.startDate}"></div><div class="field"><label>Madrid Marathon</label><input type="date" name="madridDate" value="${p.madridDate}"></div><div class="field"><label>Madrid weight (lb)</label><input type="number" step="0.1" name="madridWeight" value="${p.madridWeight}"></div><div class="field"><label>Ultimate weight (lb)</label><input type="number" step="0.1" name="ultimateWeight" value="${p.ultimateWeight}"></div><div class="field"><label>Weekly running target (mi)</label><input type="number" step="1" name="weeklyRunTarget" value="${p.weeklyRunTarget??''}"></div></div>
<div class="modal-section-title">Daily targets</div><div class="form-grid cols-2"><div class="field"><label>Calories</label><input type="number" name="calorieTarget" value="${p.calorieTarget??''}"></div><div class="field"><label>Protein (g)</label><input type="number" name="proteinTarget" value="${p.proteinTarget??''}"></div><div class="field"><label>Fibre (g)</label><input type="number" name="fibreTarget" value="${p.fibreTarget??''}"></div><div class="field"><label>Water (L)</label><input type="number" step="0.1" name="waterTarget" value="${p.waterTarget??''}"></div><div class="field"><label>Steps</label><input type="number" step="500" name="stepTarget" value="${p.stepTarget??''}"></div><div class="field"><label>Strength sessions / week</label><input type="number" min="0" max="7" name="strengthTarget" value="${p.strengthTarget}"></div><div class="field"><label>Bedtime target</label><input type="time" name="bedtimeTarget" value="${p.bedtimeTarget||'22:30'}"></div></div>
<button class="primary-btn wide" type="submit">Save targets</button></form>`);
  document.getElementById('profileForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const updated={...p,name:f.get('name').trim()||'Matt',startDate:f.get('startDate'),madridDate:f.get('madridDate'),madridWeight:Number(f.get('madridWeight')),ultimateWeight:Number(f.get('ultimateWeight')),weeklyRunTarget:Number(f.get('weeklyRunTarget')),calorieTarget:Number(f.get('calorieTarget')),proteinTarget:Number(f.get('proteinTarget')),fibreTarget:Number(f.get('fibreTarget')),waterTarget:Number(f.get('waterTarget')),stepTarget:Number(f.get('stepTarget')),strengthTarget:Number(f.get('strengthTarget')),bedtimeTarget:f.get('bedtimeTarget'),updatedAt:nowIso()};await HealthDB.put('profile',updated);state.profile=updated;closeModal();toast('Targets saved');render();};
}
function openBaselineModal(){const p=state.profile;modal(`<div class="modal-head"><div><h2>Baseline</h2><p>You can leave these blank until Tuesday morning.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="baselineForm" class="form-grid"><div class="notice">Recommended: take your Withings weigh-in first thing on 3 November, then use that as the official start weight.</div><div class="form-grid cols-2"><div class="field"><label>Starting weight (lb)</label><input type="number" step="0.1" name="startWeight" value="${p.startWeight??''}" placeholder="Enter on 3 Nov"></div><div class="field"><label>Waist (in)</label><input type="number" step="0.1" name="waist" value="${p.waist??''}"></div><div class="field"><label>Garmin VO₂ max</label><input type="number" step="1" name="vo2max" value="${p.vo2max??''}"></div><div class="field"><label>Typical weekly running (mi)</label><input type="number" step="0.1" name="weeklyRunBaseline" value="${p.weeklyRunBaseline??''}"></div></div><button class="primary-btn wide">Save baseline</button></form>`);
  document.getElementById('baselineForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const val=n=>f.get(n)===''?null:Number(f.get(n));const updated={...p,startWeight:val('startWeight'),waist:val('waist'),vo2max:val('vo2max'),weeklyRunBaseline:val('weeklyRunBaseline'),updatedAt:nowIso()};await HealthDB.put('profile',updated);if(updated.startWeight){const existing=(await HealthDB.getAll('measurements')).find(x=>x.type==='weight'&&x.date===updated.startDate&&x.source==='baseline');if(!existing)await HealthDB.put('measurements',{id:`weight_${updated.startDate}_baseline`,type:'weight',date:updated.startDate,value:updated.startWeight,unit:'lb',source:'baseline',createdAt:nowIso()});}if(updated.waist)await HealthDB.put('measurements',{id:`waist_${updated.startDate}_baseline`,type:'waist',date:updated.startDate,value:updated.waist,unit:'in',source:'baseline',createdAt:nowIso()});state.profile=updated;closeModal();toast('Baseline saved');render();};
}
function openWeightModal(){modal(`<div class="modal-head"><div><h2>Log weight</h2><p>The number is data. Add context only when something unusual may explain noise.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="weightForm" class="form-grid"><div class="form-grid cols-2"><div class="field"><label>Date</label><input type="date" name="date" value="${isoDate()}"></div><div class="field"><label>Weight (lb)</label><input type="number" step="0.1" name="weight" required autofocus></div></div><div class="field"><label>Anything unusual yesterday? (optional)</label><div class="check-grid">${[['salt','High-salt meal'],['carbs','Big carb day'],['late_meal','Late meal'],['hard_training','Hard training'],['poor_sleep','Poor sleep'],['travel','Travel']].map(([k,l])=>`<label class="check-chip"><input type="checkbox" name="context" value="${k}"><span>${l}</span></label>`).join('')}</div></div><div class="field"><label>Optional note</label><input name="note" placeholder="Anything else worth remembering"></div><button class="primary-btn wide">Save weigh-in</button></form>`);document.getElementById('weightForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),date=f.get('date'),value=Number(f.get('weight'));await HealthDB.put('measurements',{id:`weight_${date}_${Date.now()}`,type:'weight',date,value,unit:'lb',note:f.get('note'),context:f.getAll('context'),source:'manual',createdAt:nowIso()});const h=await habitFor(date);h.weighIn=true;await saveHabit(h);if(date===state.profile.startDate&&!state.profile.startWeight){const p={...state.profile,startWeight:value,updatedAt:nowIso()};await HealthDB.put('profile',p);state.profile=p;}closeModal();toast('Weight logged — trend beats noise');render();};}

function openWaistModal(){modal(`<div class="modal-head"><div><h2>Log waist</h2><p>A useful non-scale measure every few weeks.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="waistForm" class="form-grid"><div class="form-grid cols-2"><div class="field"><label>Date</label><input type="date" name="date" value="${isoDate()}"></div><div class="field"><label>Waist (in)</label><input type="number" step="0.1" name="waist" required></div></div><button class="primary-btn wide">Save</button></form>`);document.getElementById('waistForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await HealthDB.put('measurements',{id:uid('waist'),type:'waist',date:f.get('date'),value:Number(f.get('waist')),unit:'in',source:'manual',createdAt:nowIso()});closeModal();toast('Waist logged');render();};}
function openActivityModal(){modal(`<div class="modal-head"><div><h2>Add activity</h2><p>Garmin will eventually supply the numbers; your subjective feel adds context Garmin cannot know.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="activityForm" class="form-grid"><div class="form-grid cols-2"><div class="field"><label>Date</label><input type="date" name="date" value="${isoDate()}"></div><div class="field"><label>Type</label><select name="type"><option value="run">Run</option><option value="strength">Strength</option><option value="swim">Swim</option><option value="football">Football</option><option value="walk">Walk</option><option value="cycle">Cycle</option><option value="other">Other</option></select></div><div class="field"><label>Title</label><input name="title" placeholder="Easy run / upper body"></div><div class="field"><label>Distance (miles)</label><input type="number" step="0.01" name="distanceMiles"></div><div class="field"><label>Duration (minutes)</label><input type="number" step="1" name="durationMinutes"></div><div class="field"><label>Average HR</label><input type="number" step="1" name="avgHr"></div><div class="field"><label>How did it feel?</label><select name="feel"><option value="">Not rated</option><option>Easy</option><option>Good</option><option>Hard</option><option>Awful</option></select></div><div class="field"><label>Enjoyment (1–5)</label><select name="enjoyment"><option value="">Not rated</option>${[1,2,3,4,5].map(x=>`<option value="${x}">${x}</option>`).join('')}</select></div><div class="field"><label>Strength focus (if relevant)</label><select name="strengthFocus"><option value="">—</option><option>Full body</option><option>Upper</option><option>Lower</option><option>Core</option></select></div><div class="field"><label>Effort</label><select name="effort"><option value="">—</option><option>Easy</option><option>Moderate</option><option>Hard</option></select></div></div><div class="field"><label>Notes</label><textarea name="notes" placeholder="How it felt, niggles, context..."></textarea></div><button class="primary-btn wide">Save activity</button></form>`);document.getElementById('activityForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),type=f.get('type'),date=f.get('date');await HealthDB.put('activities',{id:uid('activity'),date,type,title:f.get('title')||type,distanceMiles:f.get('distanceMiles')?Number(f.get('distanceMiles')):null,durationMinutes:f.get('durationMinutes')?Number(f.get('durationMinutes')):null,avgHr:f.get('avgHr')?Number(f.get('avgHr')):null,feel:f.get('feel'),enjoyment:f.get('enjoyment')?Number(f.get('enjoyment')):null,strengthFocus:f.get('strengthFocus'),effort:f.get('effort'),notes:f.get('notes'),source:'manual',createdAt:nowIso()});const h=await habitFor(date);h.training=true;await saveHabit(h);closeModal();toast('Activity saved');render();};}

function openNutritionModal(){const p=state.profile;HealthDB.get('nutrition',isoDate()).then(n=>{n=n||{};modal(`<div class="modal-head"><div><h2>Nutrition totals</h2><p>Use Nutracheck for food logging. This dashboard wants the useful outcome and how the day felt.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="nutritionForm" class="form-grid"><div class="form-grid cols-2"><div class="field"><label>Date</label><input type="date" name="date" value="${isoDate()}"></div><div class="field"><label>Calories</label><input type="number" name="calories" value="${n.calories??''}" placeholder="${p.calorieTarget?`Target ${p.calorieTarget}`:'From Nutracheck'}"></div><div class="field"><label>Protein (g)</label><input type="number" name="protein" value="${n.protein??''}" placeholder="${p.proteinTarget?`Target ${p.proteinTarget}`:'Set your target'}"></div><div class="field"><label>Fibre (g)</label><input type="number" name="fibre" value="${n.fibre??''}" placeholder="${p.fibreTarget?`Target ${p.fibreTarget}`:'Set your target'}"></div><div class="field"><label>Fruit & veg portions</label><input type="number" step="1" name="fruitVeg" value="${n.fruitVeg??''}"></div><div class="field"><label>How did eating feel?</label><select name="eatingFeel"><option value="">Not rated</option>${['Easy','Hungry','Snacky','Overate','Very full'].map(x=>`<option ${n.eatingFeel===x?'selected':''}>${x}</option>`).join('')}</select></div></div><button class="primary-btn wide">Save totals</button></form>`);document.getElementById('nutritionForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),date=f.get('date'),num=k=>f.get(k)===''?null:Number(f.get(k));const row={id:date,date,calories:num('calories'),protein:num('protein'),fibre:num('fibre'),fruitVeg:num('fruitVeg'),eatingFeel:f.get('eatingFeel'),source:'manual/nutracheck',updatedAt:nowIso()};await HealthDB.put('nutrition',row);const h=await habitFor(date);if(row.calories!=null&&state.profile.calorieTarget)h.nutrition=row.calories<=state.profile.calorieTarget;if(row.protein!=null&&state.profile.proteinTarget)h.protein=row.protein>=state.profile.proteinTarget;if((row.fibre!=null||row.fruitVeg!=null)&&state.profile.fibreTarget)h.fibre=(row.fibre||0)>=state.profile.fibreTarget||(row.fruitVeg||0)>=5;await saveHabit(h);closeModal();toast('Nutrition totals saved');render();};});}

function openTodayNumbersModal(){habitFor().then(h=>HealthDB.get('nutrition',isoDate()).then(n=>{n=n||{};modal(`<div class="modal-head"><div><h2>Today's numbers</h2><p>Fast manual entry until the data sources are connected.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="todayNumbersForm" class="form-grid"><div class="form-grid cols-2"><div class="field"><label>Steps</label><input type="number" name="steps" value="${h.stepsValue??''}" placeholder="${state.profile.stepTarget??''}"></div><div class="field"><label>Water (L)</label><input type="number" step="0.1" name="water" value="${h.waterLitres??''}" placeholder="${state.profile.waterTarget??''}"></div><div class="field"><label>Calories</label><input type="number" name="calories" value="${n.calories??''}"></div><div class="field"><label>Protein (g)</label><input type="number" name="protein" value="${n.protein??''}"></div><div class="field"><label>Fibre (g)</label><input type="number" name="fibre" value="${n.fibre??''}"></div><div class="field"><label>Fruit & veg</label><input type="number" name="fruitVeg" value="${n.fruitVeg??''}"></div></div><button class="primary-btn wide">Save today</button></form>`);document.getElementById('todayNumbersForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),num=k=>f.get(k)===''?null:Number(f.get(k));h.stepsValue=num('steps');h.waterLitres=num('water');if(h.stepsValue!=null&&state.profile.stepTarget)h.steps=h.stepsValue>=state.profile.stepTarget;if(h.waterLitres!=null&&state.profile.waterTarget)h.water=h.waterLitres>=state.profile.waterTarget;await saveHabit(h);const row={id:isoDate(),date:isoDate(),calories:num('calories'),protein:num('protein'),fibre:num('fibre'),fruitVeg:num('fruitVeg'),source:'manual/nutracheck',updatedAt:nowIso()};await HealthDB.put('nutrition',row);if(row.calories!=null&&state.profile.calorieTarget)h.nutrition=row.calories<=state.profile.calorieTarget;if(row.protein!=null&&state.profile.proteinTarget)h.protein=row.protein>=state.profile.proteinTarget;if((row.fibre!=null||row.fruitVeg!=null)&&state.profile.fibreTarget)h.fibre=(row.fibre||0)>=state.profile.fibreTarget||(row.fruitVeg||0)>=5;await saveHabit(h);closeModal();toast('Today updated');render();};}));}
function openJournalModal(){modal(`<div class="modal-head"><div><h2>Add context</h2><p>Useful for explaining odd data later.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="journalForm" class="form-grid"><div class="form-grid cols-2"><div class="field"><label>Date</label><input type="date" name="date" value="${isoDate()}"></div><div class="field"><label>Type</label><select name="type"><option>Note</option><option>Illness</option><option>Niggle / injury</option><option>Poor sleep</option><option>Fatigue</option><option>Holiday / travel</option></select></div><div class="field"><label>Severity</label><select name="severity"><option value="">Not rated</option><option>Mild</option><option>Moderate</option><option>Significant</option></select></div></div><div class="field"><label>What happened?</label><textarea name="note" required></textarea></div><button class="primary-btn wide">Save note</button></form>`);document.getElementById('journalForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await HealthDB.put('journal',{id:uid('journal'),date:f.get('date'),type:f.get('type'),severity:f.get('severity'),note:f.get('note'),createdAt:nowIso()});closeModal();toast('Context saved');render();};}

async function openDailyCheckinModal(){const existing=await dailyCheckin()||{id:`daily_${isoDate()}`,date:isoDate(),energy:3,hunger:3,sleep:'OK',body:'Normal',mood:'OK',factors:[]};const factors=new Set(existing.factors||[]);modal(`<div class="modal-head"><div><h2>How are you today?</h2><p>Context for the coach, not another score to game.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="checkinForm" class="form-grid"><div class="form-grid cols-2"><div class="field"><label>Energy (1–5)</label><select name="energy">${[1,2,3,4,5].map(x=>`<option value="${x}" ${Number(existing.energy)===x?'selected':''}>${x}${x===1?' — flat':x===5?' — flying':''}</option>`).join('')}</select></div><div class="field"><label>Hunger (1–5)</label><select name="hunger">${[1,2,3,4,5].map(x=>`<option value="${x}" ${Number(existing.hunger)===x?'selected':''}>${x}${x===1?' — low':x===5?' — constant':''}</option>`).join('')}</select></div><div class="field"><label>Sleep</label><select name="sleep">${['Poor','OK','Good'].map(x=>`<option ${existing.sleep===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Body</label><select name="body">${['Fresh','Normal','Sore'].map(x=>`<option ${existing.body===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Mood</label><select name="mood">${['Low','OK','Good'].map(x=>`<option ${existing.mood===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label>Anything affecting today?</label><div class="check-grid">${[['poor_sleep','Poor sleep'],['illness','Illness'],['injury','Injury'],['stress','Stress'],['travel','Travel'],['late_night','Late night']].map(([k,l])=>`<label class="check-chip"><input type="checkbox" name="factors" value="${k}" ${factors.has(k)?'checked':''}><span>${l}</span></label>`).join('')}</div></div><button class="primary-btn wide">Save check-in</button></form>`);document.getElementById('checkinForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await HealthDB.put('checkins',{...existing,id:`daily_${isoDate()}`,date:isoDate(),energy:Number(f.get('energy')),hunger:Number(f.get('hunger')),sleep:f.get('sleep'),body:f.get('body'),mood:f.get('mood'),factors:f.getAll('factors'),updatedAt:nowIso()});const h=await habitFor();h.checkin=true;await saveHabit(h);closeModal();toast('Check-in saved');render();};}
async function openTomorrowPlanModal(){const date=addDays(isoDate(),1),existing=await HealthDB.get('plans',date)||{id:date,date,activity:'',calorieTarget:state.profile.calorieTarget,stepTarget:state.profile.stepTarget,note:''};modal(`<div class="modal-head"><div><h2>Plan tomorrow</h2><p>Give tomorrow’s coach something concrete to hold you accountable to.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="planForm" class="form-grid"><div class="field"><label>Movement / training intention</label><input name="activity" value="${esc(existing.activity||'')}" placeholder="e.g. swim, upper-body gym, easy run, rest"></div><div class="form-grid cols-2"><div class="field"><label>Calorie target</label><input type="number" name="calorieTarget" value="${existing.calorieTarget??''}"></div><div class="field"><label>Step target</label><input type="number" name="stepTarget" value="${existing.stepTarget??''}"></div></div><div class="field"><label>One thing that will make tomorrow easier</label><textarea name="note" placeholder="Pack lunch, put gym kit out, plan dinner...">${esc(existing.note||'')}</textarea></div><button class="primary-btn wide">Save tomorrow’s plan</button></form>`);document.getElementById('planForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await HealthDB.put('plans',{id:date,date,activity:f.get('activity').trim(),calorieTarget:f.get('calorieTarget')?Number(f.get('calorieTarget')):null,stepTarget:f.get('stepTarget')?Number(f.get('stepTarget')):null,note:f.get('note').trim(),updatedAt:nowIso()});closeModal();toast('Tomorrow planned');render();};}
async function openSupplementsModal(){let cfg=await HealthDB.get('settings','supplements');if(!cfg){cfg={id:'supplements',items:['Daily vitamins']};await HealthDB.put('settings',cfg);}const h=await habitFor(),done=new Set(h.supplementsDone||[]);modal(`<div class="modal-head"><div><h2>Supplements</h2><p>Adherence only — the dashboard does not choose doses or recommend supplements.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="supplementForm" class="form-grid"><div class="check-grid">${cfg.items.map((x,i)=>`<label class="check-chip"><input type="checkbox" name="supp" value="${i}" ${done.has(String(i))?'checked':''}><span>${esc(x)}</span></label>`).join('')}</div><button class="primary-btn wide">Save today</button><button class="secondary-btn wide" type="button" id="editSupplementList">Edit my list</button></form>`);document.getElementById('supplementForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);h.supplementsDone=f.getAll('supp');h.vitamins=cfg.items.length>0&&h.supplementsDone.length>=cfg.items.length;await saveHabit(h);closeModal();toast(h.vitamins?'Supplements complete':'Supplement progress saved');render();};document.getElementById('editSupplementList').onclick=()=>{const value=prompt('Enter your supplement names separated by commas:',cfg.items.join(', '));if(value!=null){cfg.items=value.split(',').map(x=>x.trim()).filter(Boolean);cfg.updatedAt=nowIso();HealthDB.put('settings',cfg).then(()=>{closeModal();openSupplementsModal();});}};}
function openMomentModal(){modal(`<div class="modal-head"><div><h2>Win / wobble</h2><p>Capture the moment without turning it into a judgement.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="momentForm" class="form-grid"><div class="field"><label>What happened?</label><select name="type"><option>Temptation resisted</option><option>Off-plan meal</option><option>Off-plan day</option><option>Skipped workout</option><option>Bounce back</option><option>Other win</option></select></div><div class="field"><label>Area</label><select name="area"><option>Food / snacking</option><option>Takeaway / eating out</option><option>Training</option><option>Stress eating</option><option>Routine</option><option>Other</option></select></div><div class="field"><label>What was going on?</label><textarea name="note" placeholder="Optional context"></textarea></div><button class="primary-btn wide">Save moment</button></form>`);document.getElementById('momentForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await HealthDB.put('journal',{id:uid('moment'),date:isoDate(),type:f.get('type'),severity:'',note:`${f.get('area')}${f.get('note')?` — ${f.get('note')}`:''}`,createdAt:nowIso(),moment:true});closeModal();toast('Moment logged');render();};}
async function openMomentumBreakdown(){const h=await habitFor(),injury=await latestActiveInjury(),defs=adjustedHabitDefs(injury),m=momentum(h,defs);modal(`<div class="modal-head"><div><h2>Momentum score</h2><p>Today’s controllable behaviours. Outcomes such as weight loss earn no points.</p></div><button class="close-btn" data-close-modal>×</button></div><div class="notice">The score is intentionally behaviour-first. A noisy scale day cannot take points away from a day where you followed the plan.</div><div class="score-detail-list">${defs.map(d=>`<section class="score-detail"><div class="goal-head"><div><strong>${d.icon} ${esc(d.label)}</strong><small>${esc(d.detail)}</small></div><span class="pill ${h[d.key]?'good':''}">${h[d.key]?`+${d.points}`:`0 / ${d.points}`}</span></div></section>`).join('')}</div><section class="card compact" style="box-shadow:none;margin-top:12px"><div class="goal-head"><strong>Total today</strong><b>${m.earned}/100</b></div><p class="metric-sub">Injury-aware training substitutions change the behaviour label, not the available points.</p></section>`);}
async function openWeeklyReflectionModal(){const weekStart=mondayOf(),existing=await HealthDB.get('checkins',`weekly_${weekStart}`)||{id:`weekly_${weekStart}`,date:weekStart,rating:3,confidence:3,wentWell:'',obstacle:'',improve:''};modal(`<div class="modal-head"><div><h2>Weekly reflection</h2><p>The data says what happened. You tell the app what it felt like.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="weeklyReflectionForm" class="form-grid"><div class="form-grid cols-2"><div class="field"><label>How was the week? (1–5)</label><select name="rating">${[1,2,3,4,5].map(x=>`<option value="${x}" ${Number(existing.rating)===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Confidence in 190 lb by Madrid (1–5)</label><select name="confidence">${[1,2,3,4,5].map(x=>`<option value="${x}" ${Number(existing.confidence)===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label>What went well?</label><textarea name="wentWell">${esc(existing.wentWell||'')}</textarea></div><div class="field"><label>What got in the way?</label><select name="obstacle"><option value="">Nothing major</option>${['Hunger','Work','Family','Travel','Injury','Motivation','Planning','Poor sleep','Other'].map(x=>`<option ${existing.obstacle===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>One thing to improve next week</label><textarea name="improve">${esc(existing.improve||'')}</textarea></div><button class="primary-btn wide">Save reflection</button></form>`);document.getElementById('weeklyReflectionForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await HealthDB.put('checkins',{...existing,id:`weekly_${weekStart}`,date:weekStart,type:'weekly',rating:Number(f.get('rating')),confidence:Number(f.get('confidence')),wentWell:f.get('wentWell').trim(),obstacle:f.get('obstacle'),improve:f.get('improve').trim(),updatedAt:nowIso()});closeModal();toast('Weekly reflection saved');render();};}
async function openScoreBreakdown(){const hp=await healthPerformanceScore();modal(`<div class="modal-head"><div><h2>Health & Performance score</h2><p>Transparent maths. No mystery points.</p></div><button class="close-btn" data-close-modal>×</button></div><div class="notice">This is a motivational progress score, not a medical assessment. Components are weighted and missing components are excluded rather than scored as zero.</div><div class="score-detail-list">${hp.metrics.map(m=>`<section class="score-detail"><div class="goal-head"><div><strong>${esc(m.label)}</strong><small>${esc(m.formula)}</small></div><span class="pill">${m.value}/100 × ${m.weight}%</span></div><div class="mini-bar"><div style="width:${m.value}%"></div></div><p><b>${m.points.toFixed(1)} weighted points.</b> ${esc(m.next)}</p></section>`).join('')}</div><section class="card compact" style="box-shadow:none;margin-top:12px"><div class="goal-head"><strong>Overall</strong><b>${hp.score==null?'Building':`${hp.score}/100`}</b></div><p class="metric-sub">Weighted points are divided by the total available weighting (${hp.weightTotal}%) so a missing data source does not quietly punish you.</p></section>`);}
async function openInjuryModal(id=null){const existing=id?await HealthDB.get('injuries',id):null;const i=existing||{id:uid('injury'),startDate:isoDate(),area:'Other',side:'N/A',severity:'Moderate',restriction:'no_run',allowed:[],note:'',active:true};const allowed=new Set(i.allowed||[]);modal(`<div class="modal-head"><div><h2>${existing?'Update injury':'Add injury'}</h2><p>This changes coaching; it does not diagnose or decide what activity is medically safe.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="injuryForm" class="form-grid"><div class="notice warning">Only select activities you already know are comfortable or have been advised are appropriate. If symptoms worsen, stop and seek appropriate medical advice.</div><div class="form-grid cols-2"><div class="field"><label>Started</label><input type="date" name="startDate" value="${i.startDate}"></div><div class="field"><label>Body area</label><select name="area">${['Ankle','Foot','Lower leg','Knee','Hip','Back','Shoulder / upper body','Other'].map(v=>`<option ${i.area===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Side</label><select name="side">${['N/A','Left','Right','Both'].map(v=>`<option ${i.side===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Severity</label><select name="severity">${['Mild','Moderate','Significant'].map(v=>`<option ${i.severity===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field"><label>How should training adapt?</label><select name="restriction"><option value="modified" ${i.restriction==='modified'?'selected':''}>Niggle — modify training</option><option value="no_run" ${i.restriction==='no_run'?'selected':''}>Restricted — pause running</option><option value="recovery" ${i.restriction==='recovery'?'selected':''}>Recovery — no training target</option></select></div><div class="field"><label>Alternatives I am comfortable doing</label><div class="check-grid">${[['walk','Short walk'],['swim','Swimming'],['cycle','Easy cycling'],['upper_strength','Upper-body weights'],['lower_strength','Lower-body strength'],['mobility','Gentle mobility']].map(([k,l])=>`<label class="check-chip"><input type="checkbox" name="allowed" value="${k}" ${allowed.has(k)?'checked':''}><span>${l}</span></label>`).join('')}</div></div><div class="field"><label>Notes</label><textarea name="note" placeholder="What aggravates it, what feels okay, any context...">${esc(i.note||'')}</textarea></div><button class="primary-btn wide">${existing?'Save changes':'Activate injury-aware coaching'}</button></form>`);document.getElementById('injuryForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const row={...i,startDate:f.get('startDate'),area:f.get('area'),side:f.get('side'),severity:f.get('severity'),restriction:f.get('restriction'),allowed:f.getAll('allowed'),note:f.get('note').trim(),active:true,endDate:null,createdAt:i.createdAt||nowIso(),updatedAt:nowIso()};await HealthDB.put('injuries',row);closeModal();toast('Coaching adapted to injury');render();};}
async function logInjuryCheckin(id,status){const i=await HealthDB.get('injuries',id);if(!i)return;const checkins=(i.checkins||[]).filter(c=>c.date!==isoDate());checkins.push({date:isoDate(),status,createdAt:nowIso()});i.checkins=checkins;i.updatedAt=nowIso();await HealthDB.put('injuries',i);if(status==='worse')toast('Logged as worse — update restrictions if your safe options have changed');else toast(`Injury check-in: ${status}`);render();}
async function resolveInjury(id){const i=await HealthDB.get('injuries',id);if(!i)return;if(!confirm(`Mark ${i.area||'this injury'} as resolved today?`))return;i.active=false;i.endDate=isoDate();i.updatedAt=nowIso();await HealthDB.put('injuries',i);toast('Injury marked resolved');render();}

async function currentLesson(){const day=journeyDay();const lessons=(await HealthDB.getAll('lessons')).sort((a,b)=>a.day-b.day);return lessons.find(l=>l.day===day)||lessons.find(l=>!l.completedAt)||lessons[0];}
async function openLesson(id){const l=await HealthDB.get('lessons',id);if(!l)return;const sections=l.sections||[{heading:'Lesson',text:l.body||''}];const options=l.options||[l.answer||'Continue'];modal(`<div class="modal-head"><div><h2>${esc(l.title)}</h2><p>${esc(l.theme)} • about ${l.minutes} minutes</p></div><button class="close-btn" data-close-modal>×</button></div><div class="notice">Day ${l.day}. Completion unlocks only after you reach the end and answer the knowledge check.</div><article class="lesson-reader" id="lessonReader"><div class="lesson-summary">${esc(l.summary||'')}</div>${sections.map(s=>`<section class="lesson-section"><h3>${esc(s.heading)}</h3><p>${esc(s.text)}</p></section>`).join('')}<section class="lesson-action"><div class="metric-label">TRY THIS TODAY</div><p>${esc(l.action||'')}</p></section><section class="lesson-sources"><div class="metric-label">EVIDENCE / FURTHER READING</div>${(l.sources||[]).map(s=>`<p>• ${esc(s)}</p>`).join('')}</section><section class="lesson-quiz" id="lessonQuiz"><div class="metric-label">KNOWLEDGE CHECK</div><h3>${esc(l.question||'Ready to complete?')}</h3><div class="quiz-options">${options.map((o,i)=>`<button class="quiz-option" data-quiz-index="${i}">${esc(o)}</button>`).join('')}</div><div id="quizFeedback" class="quiz-feedback"></div></section><div class="lesson-end-marker" id="lessonEndMarker">You’ve reached the end of the lesson.</div></article><button id="completeLesson" class="primary-btn wide" disabled style="margin-top:14px">${l.completedAt?'Completed ✓':'Read to the end + answer correctly'}</button>`);
  const modalEl=document.querySelector('.modal'),btn=document.getElementById('completeLesson');let reachedEnd=!!l.completedAt,correct=!!l.completedAt;
  const update=()=>{if(l.completedAt){btn.disabled=false;btn.textContent='Completed ✓';return;}btn.disabled=!(reachedEnd&&correct);btn.textContent=btn.disabled?'Read to the end + answer correctly':'Complete lesson +5';};
  const checkScroll=()=>{if(modalEl.scrollTop+modalEl.clientHeight>=modalEl.scrollHeight-80){reachedEnd=true;update();}};modalEl.addEventListener('scroll',checkScroll);update();setTimeout(checkScroll,50);
  document.querySelectorAll('[data-quiz-index]').forEach(q=>q.onclick=()=>{const idx=Number(q.dataset.quizIndex);document.querySelectorAll('[data-quiz-index]').forEach(x=>x.classList.remove('correct','wrong'));const feedback=document.getElementById('quizFeedback');if(idx===Number(l.correct)){correct=true;q.classList.add('correct');feedback.textContent=`Correct. ${l.explanation||''}`;}else{correct=false;q.classList.add('wrong');feedback.textContent='Not quite — reread the lesson and try again.';}update();});
  btn.onclick=async()=>{if(l.completedAt){closeModal();return;}if(!(reachedEnd&&correct))return;l.completedAt=nowIso();l.quizCorrectAt=nowIso();await HealthDB.put('lessons',l);const h=await habitFor();h.learning=true;await saveHabit(h);toast('Lesson learned +5 Momentum');closeModal();render();};
}

function openSourcesModal(){modal(`<div class="modal-head"><div><h2>Data connections</h2><p>Where V0.4 stands.</p></div><button class="close-btn" data-close-modal>×</button></div><div class="notice">The app is fully usable manually. We can add integrations without changing your underlying dashboard data model.</div><div style="margin-top:12px">${dataSourceRows()}</div><div class="separator"></div><p style="font-size:.7rem;color:var(--muted);line-height:1.5">Garmin: the official Personal API is available, with activities and steps as our priority. Withings: weight first. Nutracheck: daily totals rather than individual foods. Secrets will never be hard-coded into the GitHub Pages files.</p>`);}
function openPBModal(){HealthDB.get('settings','raceRecords').then(r=>{r=r||{id:'raceRecords'};modal(`<div class="modal-head"><div><h2>Race records</h2><p>Use current-era PBs rather than comparing every day with teenage-you.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="pbForm" class="form-grid"><div class="form-grid cols-2">${[['5k','5K'],['10k','10K'],['10mile','10 mile'],['half','Half marathon'],['marathon','Marathon']].map(([k,l])=>`<div class="field"><label>${l}</label><input name="${k}" value="${esc(r[k]||'')}" placeholder="e.g. 20:26"></div>`).join('')}</div><button class="primary-btn wide">Save records</button></form>`);document.getElementById('pbForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);for(const k of ['5k','10k','10mile','half','marathon'])r[k]=f.get(k).trim();r.updatedAt=nowIso();await HealthDB.put('settings',r);closeModal();toast('Records saved');render();};});}
function openQuickAdd(){modal(`<div class="modal-head"><div><h2>Quick add</h2><p>Log the useful context, not everything.</p></div><button class="close-btn" data-close-modal>×</button></div><div class="quick-grid"><button class="quick-option" data-quick="checkin"><span>😊</span><strong>Check-in</strong><small>Energy, hunger, sleep, body, mood</small></button><button class="quick-option" data-quick="weight"><span>⚖</span><strong>Weight</strong><small>Daily Withings number + context</small></button><button class="quick-option" data-quick="nutrition"><span>🥗</span><strong>Nutrition</strong><small>Nutracheck totals + eating feel</small></button><button class="quick-option" data-quick="activity"><span>🏃</span><strong>Activity</strong><small>Training + how it felt</small></button><button class="quick-option" data-quick="vitamins"><span>💊</span><strong>Supplements</strong><small>Tick your configured list</small></button><button class="quick-option" data-quick="plan"><span>📅</span><strong>Tomorrow</strong><small>Set tomorrow’s intentions</small></button><button class="quick-option" data-quick="moment"><span>🎯</span><strong>Win / wobble</strong><small>Temptation, off-plan moment or bounce-back</small></button><button class="quick-option" data-quick="injury"><span>🩹</span><strong>Injury</strong><small>Adapt coaching and training</small></button><button class="quick-option" data-quick="waist"><span>↔</span><strong>Waist</strong><small>Periodic body measure</small></button><button class="quick-option" data-quick="journal"><span>✎</span><strong>Journal</strong><small>Illness, sleep or context</small></button><button class="quick-option" data-quick="today"><span>✓</span><strong>Today's numbers</strong><small>Steps, water, nutrition</small></button></div>`);document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>{const k=b.dataset.quick;closeModal();({checkin:openDailyCheckinModal,weight:openWeightModal,nutrition:openNutritionModal,activity:openActivityModal,vitamins:openSupplementsModal,plan:openTomorrowPlanModal,moment:openMomentModal,injury:()=>openInjuryModal(),journal:openJournalModal,waist:openWaistModal,today:openTodayNumbersModal}[k])();});}


async function loadDemoData(){
  const existing=await HealthDB.get('settings','demoSnapshot');
  if(existing){alert('Demo data is already loaded. Use “Reset demo” first if you want to restart the test drive.');return;}
  if(!confirm('Load a realistic two-week demo? Your current local data will be snapshotted first and can be restored exactly with Reset demo.'))return;
  try{
    const snapshot=await HealthDB.exportAll();
    await HealthDB.put('settings',{id:'demoSnapshot',createdAt:nowIso(),data:snapshot});
    const original=state.profile||await HealthDB.get('profile','main');
    const demoProfile={...original,startDate:'2026-10-12',startWeight:216.4,waist:42.0,vo2max:43,weeklyRunBaseline:18,weeklyRunTarget:20,stepTarget:9000,calorieTarget:2100,proteinTarget:140,fibreTarget:30,waterTarget:2.5,strengthTarget:2,updatedAt:nowIso(),demoMode:true};
    await HealthDB.put('profile',demoProfile);state.profile=demoProfile;
    const weights=[216.4,215.8,216.1,215.3,214.9,214.6,214.8,214.2,213.9,213.5,213.8,212.9,212.4,213.3,212.6];
    const starts='2026-10-12';
    for(let i=0;i<weights.length;i++){
      const date=addDays(starts,i);
      await HealthDB.put('measurements',{id:`demo_weight_${date}`,type:'weight',date,value:weights[i],unit:'lb',note:i===13?'Demo fluctuation after a good week':'Demo data',source:'demo',createdAt:`${date}T07:15:00.000Z`,demo:true});
      const good=i%5!==3;
      await HealthDB.put('habits',{id:date,date,weighIn:true,vitamins:i!==4,nutrition:good,protein:i%4!==1,fibre:i%3!==1,water:i%5!==2,training:i%3!==0,steps:i%4!==2,learning:i<10,bedtime:i%4!==0,checkin:true,stepsValue:7600+(i*317)%4200,waterLitres:2.0+(i%4)*0.2,updatedAt:nowIso(),demo:true});
      await HealthDB.put('nutrition',{id:date,date,calories:good?1880+(i%4)*75:2310,protein:125+(i%5)*7,fibre:24+(i%4)*3,fruitVeg:4+(i%3),source:'demo',updatedAt:nowIso(),demo:true});await HealthDB.put('checkins',{id:`daily_${date}`,date,energy:3+(i%3===0?1:0),hunger:2+(i%4===1?2:1),sleep:i%4===0?'Poor':'Good',body:i%3===0?'Sore':'Normal',mood:'Good',factors:i%4===0?['poor_sleep']:[],updatedAt:nowIso(),demo:true});
    }
    const demoActs=[
      ['2026-10-13','run','Easy run',5.1,47,145],['2026-10-15','strength','Full-body strength',null,32,null],['2026-10-17','run','Steady run',6.0,51,151],
      ['2026-10-19','run','Easy run',4.5,42,143],['2026-10-20','strength','Upper body',null,35,null],['2026-10-22','swim','Easy swim',null,30,null],['2026-10-24','walk','Comfortable walk',2.2,39,null]
    ];
    for(const [date,type,title,distanceMiles,durationMinutes,avgHr] of demoActs){await HealthDB.put('activities',{id:`demo_activity_${date}_${type}`,date,type,title,distanceMiles,durationMinutes,avgHr,notes:'Demo activity',source:'demo',createdAt:`${date}T12:00:00.000Z`,demo:true});}
    const lessons=await HealthDB.getAll('lessons');
    for(const lesson of lessons){if(lesson.day<=7){lesson.completedAt=`2026-10-${String(11+lesson.day).padStart(2,'0')}T19:00:00.000Z`;lesson.demoCompleted=true;await HealthDB.put('lessons',lesson);}}
    await HealthDB.put('settings',{id:'demoMode',active:true,loadedAt:nowIso(),note:'Synthetic test data only'});
    toast('Demo loaded — explore the live dashboard');
    setView('today');
  }catch(error){console.error(error);alert(`Could not load demo data: ${error.message||error}`);}
}

async function resetDemoData(){
  const snapshot=await HealthDB.get('settings','demoSnapshot');
  if(!snapshot?.data){alert('No demo snapshot found. There is nothing to reset.');return;}
  if(!confirm('Reset the demo and restore the exact local data from immediately before the demo was loaded?'))return;
  try{
    await HealthDB.replaceAll(snapshot.data);
    await ensureDefaults();
    state.profile=await HealthDB.get('profile','main');
    toast('Demo removed — your pre-demo data is restored');
    setView('today');
  }catch(error){console.error(error);alert(`Could not reset demo data: ${error.message||error}`);}
}

function bytesToBase64(bytes){let s='';for(const b of bytes)s+=String.fromCharCode(b);return btoa(s);}
function base64ToBytes(s){const raw=atob(s),out=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);return out;}
async function deriveKey(password,salt){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
async function exportEncryptedBackup(){const password=prompt('Choose a password for this Health Dashboard backup. You will need the same password to restore it.');if(!password)return;try{toast('Preparing encrypted backup…');const data=await HealthDB.exportAll();const payload={format:'health-dashboard-backup',formatVersion:1,appVersion:APP_VERSION,createdAt:nowIso(),data};const plain=new TextEncoder().encode(JSON.stringify(payload));const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12));const key=await deriveKey(password,salt);const cipher=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain));const wrapper={format:'health-dashboard-encrypted',version:1,kdf:'PBKDF2-SHA256',iterations:250000,cipher:'AES-256-GCM',salt:bytesToBase64(salt),iv:bytesToBase64(iv),data:bytesToBase64(cipher)};const blob=new Blob([JSON.stringify(wrapper)],{type:'application/octet-stream'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`HealthDashboard-${isoDate()}-v${APP_VERSION}.healthdash`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);await HealthDB.put('settings',{id:'backupMeta',lastBackupAt:nowIso(),lastBackupVersion:APP_VERSION});toast('Encrypted backup created');render();}catch(error){console.error(error);alert(`Backup failed: ${error.message||error}`);}}
async function restoreEncryptedBackup(file){const password=prompt('Enter the password used when this backup was created.');if(!password)return;try{const wrapper=JSON.parse(await file.text());if(wrapper.format!=='health-dashboard-encrypted')throw new Error('Wrong file format');const key=await deriveKey(password,base64ToBytes(wrapper.salt));const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:base64ToBytes(wrapper.iv)},key,base64ToBytes(wrapper.data));const payload=JSON.parse(new TextDecoder().decode(plain));if(payload.format!=='health-dashboard-backup'||!payload.data)throw new Error('Invalid backup payload');if(!confirm(`Restore Health Dashboard backup from ${new Date(payload.createdAt).toLocaleString('en-GB')}? This replaces the local data on this device.`))return;await HealthDB.replaceAll(payload.data);await ensureDefaults();state.profile=await HealthDB.get('profile','main');closeModal();toast('Backup restored');setView('today');}catch(error){console.error(error);alert('Restore failed. Check the backup file and password.');}}
async function checkDeployedVersion(){try{const res=await fetch(`./version.json?t=${Date.now()}`,{cache:'no-store'});const info=await res.json();if(info.version===APP_VERSION)toast(`You are running deployed v${APP_VERSION}`);else alert(`This device is running v${APP_VERSION}, but GitHub has v${info.version}. Tap “Reload latest”.`);}catch{toast('Could not check GitHub right now');}}
async function reloadLatest(){try{if('serviceWorker'in navigator){const regs=await navigator.serviceWorker.getRegistrations();for(const r of regs)await r.update();}const keys=await caches.keys();await Promise.all(keys.filter(k=>k.startsWith('health-dashboard-')).map(k=>caches.delete(k)));location.reload();}catch{location.reload();}}

async function init(){await ensureDefaults();document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.getElementById('quickAddButton').onclick=openQuickAdd;document.getElementById('settingsButton').onclick=()=>{state.view='settings';document.querySelectorAll('.nav-item').forEach(b=>b.classList.remove('active'));render();};if('serviceWorker'in navigator){try{await navigator.serviceWorker.register('./sw.js');}catch(e){console.warn('Service worker registration failed',e);}}await render();}
init();
